var n=`0683-cafriela`;var t=`world-0683`;var a=`GW`;var r=`western-africa`;var s=4;var o=99;var l={en:`Cafriela`,ua:`Кафрієла`};var g={en:`Cafriela is a Guinea-Bissau classic prepared with chicken thigh, garlic, lemon juice, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Кафрієла, страва кухні країни Гвінея-Бісау зі складниками: куряче стегно, часник, лимонний сік, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 60 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 60 хвилин.`,t:[`marinating`],m:60,i:[[`chicken-thigh`,800,`g`],[`garlic`,5,`clove`],[`lemon-juice`,75,`ml`],[`hot-paprika`,5,`g`]]},{en:`Grill over medium-high heat for about 24 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 24 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:24,i:[[`extra-virgin-olive-oil`,40,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,230,`g`],[`red-bell-pepper`,220,`g`],[`tomato`,300,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`]]}];var u={slug:n,id:t,country:`GW`,region:r,servings:4,minutes:99,title:l,text:g,steps:h};export{a as country,u as default,t as id,o as minutes,r as region,s as servings,n as slug,h as steps,g as text,l as title};